def ruta_recurso(ruta_relativa):
    if hasattr(sys, "_MEIPASS"):
        ruta_base = sys._MEIPASS
    else:
        ruta_base = os.path.abspath(".")

    return os.path.join(ruta_base, ruta_relativa)

