        self.var_tri_media_b.set(
            f"{resumen['media_b']:.3f}"
        )
        self.var_tri_media_c.set(
            f"{resumen['media_c']:.3f}"
        )

        if resumen["items_k"]:
            self.var_tri_k.set(
                ", ".join(resumen["items_k"])
            )
        else:
            self.var_tri_k.set("Ninguno")


